<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); $initials = static function (string $name): string { $parts = preg_split('/\s+/', trim($name)) ?: []; $value = ''; foreach (array_slice($parts, 0, 2) as $part) { $value .= strtoupper(substr($part, 0, 1)); } return $value ?: 'AT'; }; ?>
<section class="portal-page-heading athlete-profile"><?php if ($athlete['photo_path']): ?><img class="portal-athlete-photo portal-athlete-photo-large" src="<?= $e($base . '/atletas/' . $athlete['id'] . '/foto') ?>" alt="Foto de <?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?>"><?php else: ?><span class="athlete-avatar-fallback portal-athlete-photo-large" aria-label="Avatar provisório de <?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?>"><?= $e($initials((string) ($athlete['sporting_name'] ?: $athlete['full_name']))) ?></span><?php endif; ?><p class="eyebrow"><?= $e($championship['name']) ?></p><h1><?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?></h1><p><?= $e($athlete['position_name']) ?> · <a href="<?= $e($base . '/equipes/' . rawurlencode($athlete['team_slug'])) ?>"><?= $e($athlete['team_name']) ?></a></p><?php if ($athlete['preferred_number']): ?><span class="portal-badge">Número <?= (int) $athlete['preferred_number'] ?></span><?php endif; ?></section>
